'use strict';
// Plants vs. Zombies Builder — dependency-free, offline edition.
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const uid=()=>crypto.randomUUID?crypto.randomUUID():Math.random().toString(36).slice(2);
const clone=o=>JSON.parse(JSON.stringify(o));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b64=s=>btoa(Array.from(new TextEncoder().encode(s),b=>String.fromCharCode(b)).join(''));
const un64=s=>new TextDecoder().decode(Uint8Array.from(atob(s),c=>c.charCodeAt(0)));
const svg=s=>'data:image/svg+xml;base64,'+b64(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 120 130">${s}</svg>`);
const ATTACKS={shot:'Straight shot',lob:'Lobbed projectile',double:'Double shot',triple:'Three-lane shot',radial:'Radial burst',rear:'Forward + rear shot',pierce:'Piercing shot',splash:'Splash projectile',homing:'Homing shot',boomerang:'Boomerang',laser:'Lane laser',chain:'Chain lightning',melee:'Melee strike',chomp:'Chomp / instant devour',explode:'Self-destruct explosion',mine:'Contact mine',sun:'Produce sun',heal:'Heal nearby allies',buff:'Boost nearby allies',freeze:'Freeze lane',push:'Wind / push enemies',pull:'Pull enemies closer',summon:'Summon ally',transform:'Transform self',snipe:'Snipe weakest enemy',drain:'Drain life',teleport:'Teleport toward enemy',shield:'Restore own health',"crossLaser":"Cross-shaped laser","globalStrike":"Board-wide strike","cleave":"Close-range cleave","execute":"Execute wounded enemy","percentHit":"Current-health damage","armorBreak":"Corrode armor","weaken":"Weaken enemy attacks","silence":"Silence enemy abilities","root":"Root enemies in place","curse":"Vulnerability curse","mark":"Mark priority target","cleanse":"Cleanse allies","barrier":"Temporary damage barrier","reflect":"Reflect projectiles","dodge":"Evade the next hit","berserk":"Berserk stance","grow":"Grow maximum health","sunSteal":"Sun siphon","sunMagnet":"Collect nearby sun","cooldownReduce":"Accelerate recharge","trap":"Lingering ground trap","poisonCloud":"Poison cloud","fireTrail":"Burning trail","shieldBreak":"Shatter shields","blinkDodge":"Sidestep to another lane","laneSwap":"Displace enemy lane","scatterShot":"Diagonal scattershot","mortar":"Targeted mortar strike","ricochet":"Ricocheting projectile","splitter":"Fragmenting projectile","proximityHeal":"Heal weakest ally","rescue":"Rescue endangered ally"};
const MODS={slow:'Slow',poison:'Poison',burn:'Burn',stun:'Stun',knockback:'Knockback',lifesteal:'Lifesteal'};
function attack(type='shot',damage=20,interval=1.6){return {type,damage,interval,range:900,count:1,mods:[],target:''};}
function unit(side,name,kind,color,attacks=[]){return {id:uid(),name,side,hp:side==='plant'?180:220,cost:100,recharge:5,speed:side==='plant'?0:19,startLocked:false,color,scale:1,armor:0,placement:'ground',traits:[],art:'',stateMedia:{},idle:'',action:'',death:'',projectile:'',attackSound:'',deathSound:'',spawnSound:'',attacks};}
function lawn(name,rows=5,cols=9){return {id:uid(),name,rows,cols,tiles:Array(rows*cols).fill('grass'),background:'',music:'',gimmick:'none',gimmickInterval:18,weather:'clear',weatherIntensity:1,weatherEffects:true};}
function level(name,lawnId,plants,zombies){return {id:uid(),name,lawnId,thumbnail:'',weather:'inherit',weatherIntensity:1,weatherEffects:true,locked:[],unlocks:[],sun:200,sunInterval:8,sunValue:25,waves:4,spawnInterval:5,waveDuration:25,endless:false,conveyor:false,seedSlots:8,pool:zombies.map(z=>({id:z.id,weight:1,minWave:1})),allowed:plants.map(p=>p.id),preplaced:[],dialogue:[],rules:[]};}
function defaults(){return {format:'pvzb-pack',version:1,edition:'release-1.1',title:'Untitled project',progress:{unlocked:[],completed:[]},plants:[],zombies:[],lawns:[],levels:[],campaigns:[]};}
let project=defaults(),page='home',selected={},brush='grass',battle=null,db=null,persistTimer,saveVersion=0,writeChain=Promise.resolve(),savedState='Ready',audio=null,muted=false;
const app=$('#app');
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',3500);}
function download(name,text,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);}
function saveStatus(text){savedState=text;const el=$('#saveState');if(el)el.textContent=text;}
function save(){saveStatus('Saving…');clearTimeout(persistTimer);persistTimer=setTimeout(()=>{const snapshot=clone(project);writeChain=writeChain.then(()=>new Promise(resolve=>{if(!db){saveStatus('Export to keep changes');resolve();return;}const tx=db.transaction('projects','readwrite');tx.objectStore('projects').put(snapshot,'current');tx.oncomplete=()=>{saveStatus('Saved on this device');resolve();};tx.onerror=()=>{saveStatus('Storage full — export your pack');toast(savedState);resolve();};}));},250);}
function stopAudio(){if(audio){audio.pause();audio=null;}}
function music(src){stopAudio();if(src&&!muted){audio=new Audio(src);audio.loop=true;audio.volume=.4;audio.play().catch(()=>{});}}
function sfx(src){if(!src||muted)return;const a=new Audio(src);a.volume=.45;a.play().catch(()=>{});}
function navigate(p){stopNpcDialogue();stopStatePreview();stopEntityAudio();if(battle){battle=null;stopAudio();}page=p;render();}
function shell(content,title,subtitle='',actions=''){
 const links=[['home','Menu'],['play','Play level'],['plants','Plants'],['zombies','Zombies'],['lawns','Lawns'],['levels','Levels'],['campaigns','Campaigns'],['packs','Packs'],['help','Guide']];
 app.innerHTML=`<div class="shell page-${page}"><nav class="gameNav"><button data-nav="home">‹ Back to menu</button><div class="navLinks">${links.slice(1).map(([id,n])=>`<button class="${page===id?'active':''}" data-nav="${id}">${n}</button>`).join('')}</div><span id="saveState">${savedState}</span></nav><main><header><div><h1>${title}</h1>${subtitle?`<div class="muted">${subtitle}</div>`:''}</div><div class="toolbar">${actions}</div></header>${content}</main></div>`;
 $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
}
function renderHome(){
 app.innerHTML=`<div class="homeMenu"><img class="homeLogo" src="${UI_ASSETS.logo}" alt="Plants vs. Zombies Build"><span class="builderEdition">BUILDER · CREATIVE EDITION 1.1</span><div class="mainLinks"><button id="quickPlay" data-nav="play">Play level</button><button data-nav="levels">Make level</button><button id="quickBuild">Make plant</button><button id="newZombie">Make zombie</button><button data-nav="plants">Edit plant</button><button data-nav="zombies">Edit zombie</button></div><div class="menuExtras"><button data-nav="campaigns">Campaigns</button><button data-nav="lawns">Lawns</button><button data-nav="packs">Import / Export</button><button data-nav="help">Field guide</button></div><div class="workshopStatus">${project.plants.length+project.zombies.length+project.lawns.length+project.levels.length+project.campaigns.length===0?'Empty workshop · Create your own plants, zombies and worlds.':`${project.plants.length} plants · ${project.zombies.length} zombies · ${project.levels.length} levels`}</div><div class="menuFoot">410 abilities · State animations & SFX · Offline</div></div>`;
 $$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
 $('#quickBuild').onclick=()=>{page='plants';render();$('#new').click();};$('#newZombie').onclick=()=>{page='zombies';render();$('#new').click();};
}
function renderUnits(kind){
 renderUnitsLegacy(kind);const u=chosen(kind);if(!u)return;
 const root=$('.shell');root.classList.add('makerScreen');
 const form=$('.editor > div:last-child');form.classList.add('makerForm');const panel=form.querySelector('.panel');panel.classList.add('makerDrawer');
 const list=$('.editor > .list');list.classList.add('makerCollection');
 const sections=[...panel.querySelectorAll(':scope > .section')];sections[0]?.classList.add('abilitySection');sections[1]?.classList.add('mediaSection');
 const stage=document.createElement('section');stage.className='makerStage';stage.innerHTML=`<div class="makerName">Name: <button id="stageName">${esc(u.name)} (..)</button></div><div class="stageStats"><b>Stats</b><div>HP <span id="stageHp">${u.hp}</span></div>${kind==='plants'?`<div>Sun <span id="stageCost">${u.cost}</span></div>`:''}<div>Speed <span id="stageSpeed">${u.speed}</span></div><div class="stageRecipe">Abilities: ${u.attacks.length}</div><button data-drawer="stats">Edit stats</button><button data-drawer="abilities">Abilities (${u.attacks.length})</button><button data-drawer="media">Import art / sounds</button><button id="openCollection">Choose ${kind==='plants'?'plant':'zombie'}</button></div><img id="stageSprite" src="${esc(defaultEntityImage(u)||EMPTY_IMAGE)}" alt="${esc(u.name)}"><div id="stageEmpty" class="stageEmpty" ${defaultEntityImage(u)?'hidden':''}>No art yet<br><button data-drawer="media">Import PNG / GIF</button></div><div class="stageActions"><button id="makerSave">Save</button><button id="makerBack">Back to menu</button></div><button class="drawerClose" id="closeDrawer">× Close editor</button>`;
 $('.editor').prepend(stage);const setMode=mode=>{root.dataset.drawer=mode;root.classList.add('drawerOpen');root.classList.remove('collectionOpen');};
 $$('[data-drawer]').forEach(b=>b.onclick=()=>setMode(b.dataset.drawer));$('#stageName').onclick=()=>{setMode('stats');$('[data-key="name"]').focus();};$('#closeDrawer').onclick=()=>{root.classList.remove('drawerOpen','collectionOpen');};$('#openCollection').onclick=()=>{root.classList.toggle('collectionOpen');root.classList.remove('drawerOpen');};$('#makerSave').onclick=()=>{save();toast('Saved! Your creation is ready.');};$('#makerBack').onclick=()=>navigate('home');
 const toolbar=$('header .toolbar');toolbar.querySelectorAll('button').forEach(b=>stage.querySelector('.stageActions').prepend(b));
 // Keep the stage live while editing, without replacing focused inputs.
 panel.addEventListener('change',()=>{const img=$('#stageSprite');if(img)img.src=defaultEntityImage(u)||EMPTY_IMAGE;if($('#stageEmpty'))$('#stageEmpty').hidden=!!defaultEntityImage(u);$('#stageName').textContent=u.name+' (..)';$('#stageHp').textContent=u.hp;if($('#stageCost'))$('#stageCost').textContent=u.cost;$('#stageSpeed').textContent=u.speed;});
 enhanceAbilityPicker(u,root);installStateEditor(u,root);installTabletMaker(u,root);enhanceTouchNumbers(root);
}
function headActions(kind){return `<button id="duplicate">Duplicate</button><button id="delete" class="danger">Delete</button>`;}
function field(key,label,value,type='text',min,max){return `<label class="field">${label}<input data-key="${key}" type="${type}" value="${esc(value)}" ${min!==undefined?`min="${min}"`:''} ${max!==undefined?`max="${max}"`:''} ${type==='number'?'step="any" inputmode="decimal"':''}></label>`;}
function selectField(key,label,value,options){return `<label class="field">${label}<select data-key="${key}">${Object.entries(options).map(([v,l])=>`<option value="${esc(v)}" ${String(value)===v?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function checkField(key,label,value){return `<label><input type="checkbox" data-key="${key}" ${value?'checked':''}> ${label}</label>`;}
function bindFields(obj,root=document,after=()=>{}){root.querySelectorAll('[data-key]').forEach(el=>el.onchange=()=>{let v=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.type==='number'){if(!Number.isFinite(v))v=0;if(el.min!=='')v=Math.max(Number(el.min),v);if(el.max!=='')v=Math.min(Number(el.max),v);el.value=v;}obj[el.dataset.key]=v;save();after(el.dataset.key);});enhanceTouchNumbers(root);}
function media(key,label,obj,audioFile=false){return `<div class="media"><b>${label}</b>${obj[key]?(audioFile?`<audio controls src="${esc(obj[key])}"></audio>`:`<img src="${esc(obj[key])}" alt="${label}">`):'<span class="badge">No media attached</span>'}<input type="file" data-media="${key}" accept="${audioFile?'audio/mpeg,audio/wav,.mp3,.wav':'image/png,image/gif,.png,.gif'}"><div class="row"><button class="small" data-paste="${key}">Paste base64</button><button class="small" data-clear="${key}">Clear</button></div></div>`;}
function validData(src,audioFile=false){return typeof src==='string'&&new RegExp('^data:'+(audioFile?'audio/(mpeg|mp3|wav|x-wav|wave|vnd.wave)':'image/(png|gif|svg\\+xml)')+';base64,[A-Za-z0-9+/=\\s]+$').test(src);}
function bindMedia(obj){bindScopedMedia(obj,document);}
function chosen(kind){if(!project[kind].some(x=>x.id===selected[kind]))selected[kind]=project[kind][0]?.id;return project[kind].find(x=>x.id===selected[kind]);}
function listHTML(kind){return `<div class="list"><button class="primary" id="new">＋ New ${kind==='campaigns'?'campaign':kind.slice(0,-1)}</button>${project[kind].map(x=>`<button data-id="${x.id}" class="${selected[kind]===x.id?'selected':''}">${x.art?`<img src="${esc(x.art)}" alt="">`:''}<span>${esc(x.name)}<span class="sub">${kind==='plants'?x.cost+' sun':kind==='zombies'?x.hp+' health':kind==='lawns'?x.rows+' × '+x.cols:kind==='levels'?x.waves+' waves':x.levels.length+' levels'}</span></span></button>`).join('')}</div>`;}
function bindList(kind){$$('[data-id]').forEach(b=>b.onclick=()=>{selected[kind]=b.dataset.id;render();});$('#new').onclick=()=>{let o;if(kind==='plants'||kind==='zombies')o=unit(kind==='plants'?'plant':'zombie','Untitled '+kind.slice(0,-1),kind==='plants'?'pea':'zombie','#84aa69',[]);if(kind==='lawns')o=lawn('Untitled lawn');if(kind==='levels'&&!project.lawns.length){navigate('lawns');return toast('Create a lawn first, then return to Level maker.');}if(kind==='levels')o=level('Untitled level',project.lawns[0]?.id||'',project.plants,project.zombies.slice(0,1));if(kind==='campaigns')o={id:uid(),name:'Untitled campaign',thumbnail:'',description:'',levels:[]};project[kind].push(o);selected[kind]=o.id;save();render();};const o=chosen(kind);if($('#duplicate'))$('#duplicate').onclick=()=>{if(!o)return;const c=clone(o);c.id=uid();c.name+=' copy';project[kind].push(c);selected[kind]=c.id;save();render();};if($('#delete'))$('#delete').onclick=()=>{if(!o||!confirm(`Delete “${o.name}”? References to it will also be removed.`))return;project[kind]=project[kind].filter(x=>x!==o);if(kind==='plants'){project.levels.forEach(l=>{l.allowed=l.allowed.filter(id=>id!==o.id);l.locked=l.locked.filter(id=>id!==o.id);l.unlocks=l.unlocks.filter(id=>id!==o.id);l.preplaced=l.preplaced.filter(p=>p.id!==o.id);});}if(kind==='zombies')project.levels.forEach(l=>l.pool=l.pool.filter(p=>p.id!==o.id));if(kind==='lawns')project.levels.forEach(l=>{if(l.lawnId===o.id)l.lawnId=project.lawns[0]?.id||'';});project.progress.unlocked=project.progress.unlocked.filter(id=>id!==o.id);project.progress.completed=project.progress.completed.filter(id=>id!==o.id);if(kind==='levels')project.campaigns.forEach(c=>c.levels=c.levels.filter(id=>id!==o.id));[...project.plants,...project.zombies].forEach(u=>u.attacks.forEach(a=>{if(a.target===o.id)a.target='';}));save();render();};}
function render(){const mode=$('.makerScreen')?.dataset.drawer,opened=$('.makerScreen')?.classList.contains('drawerOpen'),scroll=$('.makerDrawer')?.scrollTop||0;migrateProject(project);
 if(page==='home')return renderHome();
 if(page==='plants'||page==='zombies'){renderUnits(page);if(opened){$('.makerScreen').dataset.drawer=mode;$('.makerScreen').classList.add('drawerOpen');$('.makerDrawer').scrollTop=scroll;}return;}
 if(page==='lawns')return renderLawns();if(page==='levels')return renderLevels();if(page==='campaigns')return renderCampaigns();if(page==='play')return renderPlay();if(page==='packs')return renderPacks();if(page==='help')return renderHelp();
}
function renderUnitsLegacy(kind){const u=chosen(kind);shell(`<div class="editor">${listHTML(kind)}<div>${u?`<section class="panel"><img id="unitPreview" class="preview" src="${esc(defaultEntityImage(u)||EMPTY_IMAGE)}" alt="Unit preview"><h2>${esc(u.name)}</h2><p class="muted">${kind==='plants'?'Your newest garden invention.':'A fresh face for the horde.'}</p><div class="fields">${field('name','Name',u.name)}${field('hp','Health',u.hp,'number',1,100000)}${field('color','Projectile / effect color',u.color,'color')}${kind==='plants'?field('cost','Sun cost',u.cost,'number',0,9999)+field('recharge','Packet recharge (seconds)',u.recharge,'number',0,300)+field('speed','Move right (pixels / second; 0 = stationary)',u.speed,'number',0,200):field('speed','Walk speed (pixels / second)',u.speed,'number',0,200)}${field('armor','Damage resistance (0–0.95)',u.armor,'number',0,.95)}${field('scale','Visual scale',u.scale,'number',.3,2)}${kind==='plants'?selectField('placement','Placement',u.placement,{ground:'Ground (needs pad / pot)',water:'Aquatic / water only',roof:'Roof only',any:'Any usable tile'}):''}</div><div class="checks">${kind==='plants'?checkField('startLocked','Starts locked (earn from a level)',u.startLocked):''}${Object.entries(kind==='plants'?{platform:'Platform (supports another plant)',spikes:'Contact thorns',regenerate:'Regeneration'}:{swimmer:'Swims in water',flying:'Flying (ignores melee / mines)',vault:'Vaults first obstacle',burrow:'Burrows past first obstacle',rage:'Enrages below half health',regenerate:'Regeneration',deathSpawn:'Spawn ally on death'}).map(([v,l])=>`<label><input type="checkbox" data-trait="${v}" ${u.traits.includes(v)?'checked':''}> ${l}</label>`).join('')}</div><div class="section"><div class="row"><h2 style="flex:1">Attack recipe</h2><button id="addAttack">＋ Add behavior</button></div><p class="muted">310 available behaviors: 210 shared plus 100 for this side. Search by name, category or mechanic, then stack recipes. Each has its own timer, strength, range, and effects.</p><div id="attacks">${u.attacks.map((a,i)=>`<div class="attack" data-attack="${i}"><p class="behaviorHelp muted">${esc(BEHAVIOR_HELP[a.type]||'Uses amount, range and interval. Modifiers apply on damage.')}</p><div class="fields">${selectField('type','Behavior',a.type,Object.fromEntries(Object.entries(ATTACKS).filter(([id])=>!NEW_ABILITIES[id]?.side||NEW_ABILITIES[id].side===u.side)))}${field('damage','Damage / amount',a.damage,'number',0,100000)}${field('interval','Every (seconds)',a.interval,'number',.15,300)}${field('range','Range (pixels)',a.range,'number',20,1500)}${field('count','Burst / chain / summon count',a.count,'number',1,12)}${selectField('target','Summon / transform target',a.target,{'':'Choose unit',...Object.fromEntries(project[kind].filter(x=>x.id!==u.id).map(x=>[x.id,x.name]))})}</div><div class="checks">${Object.entries(MODS).map(([v,l])=>`<label><input type="checkbox" data-mod="${v}" ${a.mods.includes(v)?'checked':''}> ${l}</label>`).join('')}<button class="small danger removeAttack">Remove</button></div></div>`).join('')||'<p class="notice">No attacks: this unit acts as a barrier or platform.</p>'}</div></div><div class="section"><h2>Embedded media</h2><p class="muted">Files become base64 data URLs inside your pack. GIFs play as animated sprites.</p><div class="mediaGrid">${[['art','Card / default sprite'],['idle','Idle / walk GIF or PNG'],['action','Attack GIF or PNG'],['death','Death GIF or PNG'],['projectile','Projectile GIF or PNG'],['attackSound','Attack MP3 / WAV'],['deathSound','Death MP3 / WAV'],['spawnSound','Spawn MP3 / WAV']].map(([k,n])=>media(k,n,u,/Sound/.test(k))).join('')}</div></div></section>`:'<div class="empty">Create your first unit.</div>'}</div></div>`,kind==='plants'?'Plant maker':'Zombie maker','A recipe for every kind of trouble.',headActions(kind));bindList(kind);if(!u)return;bindFields(u,$('.panel'),key=>{if(key==='name'){$('h2').textContent=u.name;const label=$(`[data-id="${u.id}"] span`);if(label)label.firstChild.textContent=u.name;}});$$('[data-trait]').forEach(el=>el.onchange=()=>{u.traits=el.checked?[...u.traits,el.dataset.trait]:u.traits.filter(t=>t!==el.dataset.trait);save();});$$('[data-attack]').forEach(box=>{const i=Number(box.dataset.attack),a=u.attacks[i];bindFields(a,box,key=>{if(key==='type')box.querySelector('.behaviorHelp').textContent=BEHAVIOR_HELP[a.type]||'Uses amount, range and interval. Modifiers apply on damage.';});box.querySelectorAll('[data-mod]').forEach(el=>el.onchange=()=>{a.mods=el.checked?[...a.mods,el.dataset.mod]:a.mods.filter(m=>m!==el.dataset.mod);save();});box.querySelector('.removeAttack').onclick=()=>{u.attacks.splice(i,1);save();render();};});$('#addAttack').onclick=()=>{if(u.attacks.length>=80)return toast('A unit can stack up to 80 behavior recipes.');u.attacks.push(attack(kind==='plants'?'shot':'melee'));save();render();};bindMedia(u);}
const TILES={grass:'Grass',water:'Water',roof:'Roof',blocked:'Blocked',ice:'Ice (fast zombies)',mud:'Mud (slow zombies)',boost:'Power tile (×1.5 damage)',portal:'Portal (skips a column)'};
function gridHTML(l,attribute='data-cell'){return `<div class="gridViewport"><div class="tilegrid" style="--cols:${l.cols};grid-template-columns:repeat(${l.cols},1fr)">${l.tiles.map((t,i)=>`<button class="tile ${t}" ${attribute}="${i}" title="Row ${Math.floor(i/l.cols)+1}, column ${i%l.cols+1}: ${TILES[t]}">${{water:'≈',roof:'⌂',blocked:'×',ice:'❄',mud:'∴',boost:'✦',portal:'◉'}[t]||''}</button>`).join('')}</div></div>`;}
function renderLawnsBase(){const l=chosen('lawns');shell(`<div class="editor">${listHTML('lawns')}<section class="panel">${l?`<h2>Shape your battlefield</h2><div class="fields">${field('name','Lawn name',l.name)}${field('rows','Rows',l.rows,'number',3,7)}${field('cols','Columns',l.cols,'number',6,12)}${selectField('gimmick','Lawn gimmick',l.gimmick,{none:'None',night:'Night (no sky sun)',rain:'Rain (global slow)',sunshower:'Sun shower (double sun)',fog:'Fog (limited view)',meteor:'Meteor shower (random damage)',tide:'Changing tide (flips center rows)'})}${field('gimmickInterval','Gimmick interval (seconds)',l.gimmickInterval,'number',5,120)}${weatherFields(l,false)}</div><div class="section"><div class="row" style="margin-bottom:14px"><h3 style="flex:1">Tile brush</h3><select id="brush" style="width:auto">${Object.entries(TILES).map(([k,v])=>`<option value="${k}" ${brush===k?'selected':''}>${v}</option>`).join('')}</select><button id="fill">Fill lawn</button></div>${gridHTML(l)}<p class="muted">Click or drag to paint. Water needs aquatic plants or Lily Pads; roof tiles need Flower Pots. Ground shots hit the roof slope in the first three columns; lobbers clear it.</p></div><div class="section"><h2>World atmosphere</h2><div class="mediaGrid">${media('background','Background PNG / GIF',l)}${media('music','Unique looping MP3 / WAV',l,true)}</div></div>`:'Create a lawn to begin.'}</section></div>`,'Lawn maker','Every world deserves its own rules.',headActions('lawns'));bindList('lawns');if(!l)return;bindFields(l,$('.panel'),key=>{if(key==='rows'||key==='cols'){l.rows=Math.round(l.rows);l.cols=Math.round(l.cols);l.tiles=Array.from({length:l.rows*l.cols},(_,i)=>l.tiles[i]||'grass');save();render();}});$('#brush').onchange=e=>brush=e.target.value;$('#fill').onclick=()=>{l.tiles.fill(brush);save();render();};installTouchPainting(l);bindMedia(l);}
function renderLevelsLegacy(){const l=chosen('levels'),world=project.lawns.find(w=>w.id===l?.lawnId);shell(`<div class="editor">${listHTML('levels')}<section class="panel">${l?`<div class="row"><h2 style="flex:1">Set the stage</h2><button class="primary" id="testLevel">▷ Test level</button></div><div class="fields">${field('name','Level name',l.name)}${selectField('lawnId','Lawn',l.lawnId,Object.fromEntries(project.lawns.map(w=>[w.id,w.name])))}${field('sun','Starting sun',l.sun,'number',0,99999)}${field('sunInterval','Sky sun interval (seconds)',l.sunInterval,'number',1,120)}${field('sunValue','Sun per drop',l.sunValue,'number',1,1000)}${field('waves','Wave count',l.waves,'number',1,100)}${field('spawnInterval','Base spawn interval (seconds)',l.spawnInterval,'number',.5,60)}${field('waveDuration','Wave duration (seconds)',l.waveDuration,'number',10,180)}${field('seedSlots','Seed slots',l.seedSlots,'number',1,16)}</div><div class="checks">${checkField('endless','Endless: growing waves forever',l.endless)}${checkField('conveyor','Conveyor: free randomized packets',l.conveyor)}</div><div class="section"><h2>Cover & weather</h2><div class="mediaGrid">${media('thumbnail','Level thumbnail PNG / GIF',l)}</div><div class="fields section">${weatherFields(l,true)}</div></div><div class="section"><h2>Handmade zombie pool</h2><p class="muted">Each spawn rolls from eligible entries by weight. A weight of 3 is three times as likely as 1. Water rows require swimmers or flyers.</p>${l.pool.map((p,i)=>`<div class="poolRow" data-pool="${i}">${selectField('id','Zombie',p.id,Object.fromEntries(project.zombies.map(z=>[z.id,z.name])))}${field('weight','Weight',p.weight,'number',.1,1000)}${field('minWave','First wave',p.minWave,'number',1,100)}<button class="danger removePool">×</button></div>`).join('')}<button id="addPool">＋ Pool entry</button></div><div class="section"><h2>Seed availability & victory unlocks</h2><p class="muted">Allowed adds a packet to the selection pool. Locked bans it in this level even after an unlock. Victory unlocks a plant for later levels; mark it “Starts locked” in Plant maker first.</p><div class="availability"><div class="availabilityRow"><b>Plant</b><b>Allowed</b><b>Locked</b><b>Unlock on win</b></div>${project.plants.map(p=>`<div class="availabilityRow"><span>${esc(p.name)}${p.startLocked?' 🔒':''}</span>${['allowed','locked','unlocks'].map(k=>`<label><input aria-label="${k}: ${esc(p.name)}" type="checkbox" data-availability="${k}" data-unit="${p.id}" ${l[k].includes(p.id)?'checked':''}></label>`).join('')}</div>`).join('')}</div></div><div class="section"><h2>Pre-planted setup</h2><div class="row" style="margin-bottom:14px"><select id="preplant" style="width:auto"><option value="">Erase plants</option>${project.plants.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><span class="badge">Click tiles to place. Platforms can share a tile.</span></div>${world?gridHTML(world,'data-precell'):'<p>Create and select a lawn first.</p>'}<div class="row" style="margin-top:10px">${l.preplaced.map((p,i)=>`<button class="small" data-remove-pre="${i}">${esc(project.plants.find(x=>x.id===p.id)?.name||'Missing')} [${p.row+1},${p.col+1}] ×</button>`).join('')}</div></div><div class="section"><div class="row"><h2 style="flex:1">Opening NPC dialogue</h2><button id="addDialogue">＋ Dialogue line</button></div><p class="muted">Shown in order before the first zombie. Import each NPC’s PNG or animated GIF below, or paste a base64 image. Leave empty to skip.</p>${l.dialogue.map((d,i)=>`<div class="attack" data-dialogue="${i}"><div class="fields">${field('name','Speaker',d.name)}<label class="field full">Dialogue<textarea data-key="text">${esc(d.text)}</textarea></label></div><div class="mediaGrid">${media('portrait','NPC image / animated GIF',d)}${media('voice','Voice MP3 / WAV',d,true)}</div><button class="small danger removeDialogue">Remove line</button></div>`).join('')}</div><div class="section"><div class="row"><h2 style="flex:1">Event rules</h2><button id="addRule">＋ Event rule</button></div><p class="muted">Declarative triggers add surprises without running imported code.</p>${l.rules.map((r,i)=>`<div class="attack" data-rule="${i}"><div class="fields">${selectField('trigger','When',r.trigger,{time:'At elapsed second (once)',wave:'At wave (once)',repeat:'Every N seconds'})}${field('at','N',r.at,'number',1,9999)}${selectField('action','Action',r.action,{sun:'Add sun',spawn:'Spawn zombie',heal:'Heal all plants',damage:'Damage all zombies',message:'Show announcement'})}${field('amount','Amount / spawn count',r.amount,'number',1,9999)}${selectField('target','Zombie to spawn',r.target,{'':'Random pool entry',...Object.fromEntries(project.zombies.map(z=>[z.id,z.name]))})}${field('text','Announcement text',r.text)}</div><button class="small danger removeRule">Remove rule</button></div>`).join('')}</div>`:'Create a level to begin.'}</section></div>`,'Level maker','Design the challenge, then defend it.',headActions('levels'));bindList('levels');if(!l)return;bindFields(l,$('.panel'),key=>{if(key==='lawnId')render();});$('#testLevel').onclick=()=>prepareBattle(l.id);$$('[data-pool]').forEach(box=>{bindFields(l.pool[+box.dataset.pool],box);box.querySelector('.removePool').onclick=()=>{l.pool.splice(+box.dataset.pool,1);save();render();};});$('#addPool').onclick=()=>{if(!project.zombies.length)return toast('Create a zombie first.');l.pool.push({id:project.zombies[0].id,weight:1,minWave:1});save();render();};$$('[data-availability]').forEach(el=>el.onchange=()=>{const k=el.dataset.availability,id=el.dataset.unit;l[k]=el.checked?[...new Set([...l[k],id])]:l[k].filter(x=>x!==id);save();});bindMediaWithin(l,$('[data-media="thumbnail"]').closest('.section'));$$('[data-precell]').forEach(b=>b.onclick=()=>{const i=+b.dataset.precell,row=Math.floor(i/world.cols),col=i%world.cols,id=$('#preplant').value;if(!id)l.preplaced=l.preplaced.filter(p=>p.row!==row||p.col!==col);else {const u=project.plants.find(p=>p.id===id),platform=u.traits.includes('platform');l.preplaced=l.preplaced.filter(p=>!(p.row===row&&p.col===col&&project.plants.find(x=>x.id===p.id)?.traits.includes('platform')===platform));l.preplaced.push({id,row,col});}save();const val=id;render();$('#preplant').value=val;});$$('[data-remove-pre]').forEach(b=>b.onclick=()=>{l.preplaced.splice(+b.dataset.removePre,1);save();render();});$('#addDialogue').onclick=()=>{l.dialogue.push({name:'',text:'',portrait:'',voice:''});save();render();};$$('[data-dialogue]').forEach(box=>{const d=l.dialogue[+box.dataset.dialogue];bindFields(d,box);box.querySelector('.removeDialogue').onclick=()=>{l.dialogue.splice(+box.dataset.dialogue,1);save();render();};bindMediaWithin(d,box);});$('#addRule').onclick=()=>{l.rules.push({trigger:'time',at:30,action:'sun',amount:100,target:'',text:''});save();render();};$$('[data-rule]').forEach(box=>{bindFields(l.rules[+box.dataset.rule],box);box.querySelector('.removeRule').onclick=()=>{l.rules.splice(+box.dataset.rule,1);save();render();};});if(world)$$('[data-precell]').forEach(b=>{const i=+b.dataset.precell;const entries=l.preplaced.filter(p=>p.row===Math.floor(i/world.cols)&&p.col===i%world.cols);if(entries.length){b.style.backgroundImage=`url("${project.plants.find(p=>p.id===entries.at(-1).id)?.art||''}")`;b.style.backgroundSize='contain';b.style.backgroundPosition='center';b.style.backgroundRepeat='no-repeat';}});}
function bindMediaWithin(obj,root){bindScopedMedia(obj,root);}
function renderCampaigns(){const c=chosen('campaigns');shell(`<div class="editor">${listHTML('campaigns')}<section class="panel">${c?`<h2>Build an adventure</h2><div class="fields">${field('name','Campaign name',c.name)}<label class="field full">Description<textarea data-key="description">${esc(c.description)}</textarea></label></div><div class="section"><h2>Campaign cover</h2><div class="mediaGrid">${media('thumbnail','Campaign thumbnail PNG / GIF',c)}</div></div><div class="section"><h2>Level order</h2>${c.levels.map((id,i)=>`<div class="campaignItem"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(project.levels.find(l=>l.id===id)?.name||'Missing level')}</span><button class="small" data-up="${i}" ${i===0?'disabled':''}>↑</button><button class="small" data-down="${i}" ${i===c.levels.length-1?'disabled':''}>↓</button><button class="small danger" data-remove-level="${i}">×</button></div>`).join('')||'<p class="notice">Add a level to begin your campaign.</p>'}<div class="row" style="margin-top:16px"><select id="campaignLevel" style="width:auto">${project.levels.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select><button id="appendLevel">＋ Add level</button></div></div><div class="section row"><button id="playCampaign" class="primary">▷ Play campaign</button><button id="exportCampaign">Export campaign pack</button></div>`:'Create a campaign to begin.'}</section></div>`,'Campaign maker','Connect your worlds into something bigger.',headActions('campaigns'));bindList('campaigns');if(!c)return;bindFields(c,$('.panel'));bindMedia(c);$('#appendLevel').onclick=()=>{if(!$('#campaignLevel').value)return;c.levels.push($('#campaignLevel').value);save();render();};$$('[data-up],[data-down],[data-remove-level]').forEach(b=>b.onclick=()=>{if(b.dataset.removeLevel!==undefined)c.levels.splice(+b.dataset.removeLevel,1);else {const i=+(b.dataset.up??b.dataset.down),j=i+(b.dataset.up!==undefined?-1:1);[c.levels[i],c.levels[j]]=[c.levels[j],c.levels[i]];}save();render();});$('#playCampaign').onclick=()=>{if(!c.levels.length)return toast('Add a level first.');prepareBattle(c.levels[0],c.id,0);};$('#exportCampaign').onclick=()=>exportPack(c.id);}
function renderPlay(){if(!project.levels.length){shell(`<section class="panel emptyWorkshop"><h2>No levels yet</h2><p>Create plants and zombies, draw a lawn, then build your first level.</p><div class="row"><button class="primary" id="emptyMakePlant">Make a plant</button><button id="emptyMakeLawn">Make a lawn</button><button id="emptyImport">Import your pack</button></div></section>`,'Your workshop is empty');$('#emptyMakePlant').onclick=()=>{navigate('plants');$('#new').click();};$('#emptyMakeLawn').onclick=()=>navigate('lawns');$('#emptyImport').onclick=()=>navigate('packs');return;}shell(`<div class="cards">${project.campaigns.map(c=>`<article class="card">${thumbnailHTML(c)}<div class="eyebrow">Campaign • ${c.levels.length} levels</div><h2>${esc(c.name)}</h2><p>${esc(c.description)}</p><button class="primary" style="margin-top:20px" data-campaign="${c.id}">▷ Start adventure</button></article>`).join('')}</div><h2 style="margin-top:35px">Pick a single level</h2><div class="cards">${project.levels.map(l=>`<article class="card">${thumbnailHTML(l)}<div class="eyebrow">${esc(project.lawns.find(w=>w.id===l.lawnId)?.name||'No lawn')}</div><h2>${esc(l.name)}</h2><div class="row"><span class="pill">${l.endless?'Endless':l.waves+' waves'}</span><span class="pill">${l.sun} starting sun</span>${project.progress.completed.includes(l.id)?'<span class="pill">✓ Complete</span>':''}${l.conveyor?'<span class="pill">Conveyor</span>':''}</div><button style="margin-top:18px" data-play="${l.id}">▷ Play level</button></article>`).join('')}</div>`,'Play & explore','Every creation deserves a playthrough.');$$('[data-play]').forEach(b=>b.onclick=()=>prepareBattle(b.dataset.play));$$('[data-campaign]').forEach(b=>b.onclick=()=>{const c=project.campaigns.find(c=>c.id===b.dataset.campaign);if(!c.levels.length)return toast('This campaign has no levels yet.');prepareBattle(c.levels[0],c.id,0);});}
function campaignPack(id){const p=clone(project),c=p.campaigns.find(c=>c.id===id);p.campaigns=[c];p.levels=p.levels.filter(l=>c.levels.includes(l.id));p.lawns=p.lawns.filter(w=>p.levels.some(l=>l.lawnId===w.id));p.progress.completed=p.progress.completed.filter(id=>p.levels.some(l=>l.id===id));p.title=c.name;return p;}
function exportPack(campaignId){const p=campaignId?campaignPack(campaignId):project;download((p.title||'My garden').replace(/[^a-z0-9 _-]/gi,'_')+'.pvzpack',JSON.stringify(p));toast('Pack exported with all embedded media.');}
function exportHTML(){const doc=document.documentElement.cloneNode(true);doc.querySelector('#app').innerHTML='';doc.querySelector('#toast').textContent='';doc.querySelector('#toast').removeAttribute('style');doc.querySelector('#embeddedProject').textContent=b64(JSON.stringify(project));download('Plants_vs_Zombies_Builder_Playable.html','<!doctype html>\n'+doc.outerHTML,'text/html');toast('Standalone builder exported with your current pack.');}
function renderPacks(){shell(`<section class="panel"><div class="fields">${field('title','Project / pack title',project.title)}</div><div class="cards"><div class="card"><h2>Export a pack</h2><p>Plants, zombies, lawns, levels, campaigns and every base64 image and audio file in one portable .pvzpack file.</p><button class="primary" id="export" style="margin-top:18px">↓ Export complete pack</button></div><div class="card"><h2>Import a pack</h2><p>Merge another creator’s universe into yours, or replace your current project. No account or server needed.</p><div class="row" style="margin-top:18px"><button id="merge">Merge pack</button><button id="replace">Replace project</button></div></div><div class="card"><h2>Portable playable edition</h2><p>Export a complete offline HTML builder containing your current pack. Share it with someone who has a browser.</p><button id="exportHTML" style="margin-top:18px">↓ Export playable HTML</button></div></div><div class="section"><h2>Project health</h2><p>${project.plants.length} plants · ${project.zombies.length} zombies · ${project.lawns.length} lawns · ${project.levels.length} levels · ${project.campaigns.length} campaigns</p><p class="notice">${esc(savedState)}. Browser storage belongs to this browser and file location. Export packs regularly to keep a reliable copy. Imported files are validated and contain data, not executable scripts.</p><button id="resetProgress">Reset earned unlocks / completions</button><button class="danger" id="reset">Clear project</button></div></section>`,'Pack library','Your whole garden, in your pocket.');bindFields(project,$('.panel'));$('#export').onclick=()=>exportPack();$('#merge').onclick=()=>requestImport(true);$('#replace').onclick=()=>requestImport(false);$('#exportHTML').onclick=exportHTML;$('#resetProgress').onclick=()=>{if(confirm('Reset earned plant unlocks and level completions?')){project.progress={unlocked:[],completed:[]};save();render();}};$('#reset').onclick=()=>{if(confirm('Clear all project content? Export a pack first to keep your work.')){project=defaults();selected={};save();render();}};}
let mergeImport=false;
function requestImport(merge){mergeImport=merge;$('#packFile').value='';$('#packFile').click();}
function validatePack(p){
 if(!p||p.format!=='pvzb-pack'||p.version!==1)throw Error('This is not a version 1 PvZ Builder pack.');
 migrateProject(p);
 const arrays=['plants','zombies','lawns','levels','campaigns'],ids=new Set();
 for(const k of arrays){if(!Array.isArray(p[k])||p[k].length>2000)throw Error('Invalid collection: '+k);for(const o of p[k]){if(!o||typeof o.id!=='string'||o.id.length>100||ids.has(o.id)||typeof o.name!=='string')throw Error('Missing or duplicate IDs / names.');ids.add(o.id);}}
 function num(o,k,min,max){if(!Number.isFinite(o[k])||o[k]<min||o[k]>max)throw Error(`Invalid ${k} in ${o.name||'recipe'}.`);}
 for(const [k,side] of [['plants','plant'],['zombies','zombie']])for(const u of p[k]){if(u.side!==side)throw Error('Wrong unit side.');for(const [f,min,max] of [['hp',1,100000],['cost',0,9999],['recharge',0,300],['speed',0,200],['armor',0,.95],['scale',.3,2]])num(u,f,min,max);if(!/^#[0-9a-f]{6}$/i.test(u.color))throw Error('Invalid unit color.');if(!['ground','water','roof','any'].includes(u.placement)||!Array.isArray(u.traits)||u.traits.some(t=>!['platform','spikes','regenerate','swimmer','flying','vault','burrow','rage','deathSpawn'].includes(t)))throw Error('Invalid unit traits.');if(!Array.isArray(u.attacks)||u.attacks.length>80)throw Error('Too many attacks.');for(const a of u.attacks){if(NEW_ABILITIES[a.type]?.side&&NEW_ABILITIES[a.type].side!==u.side)throw Error('Ability belongs to the other side.');if(!Object.hasOwn(ATTACKS,a.type)||!Array.isArray(a.mods)||a.mods.some(m=>!Object.hasOwn(MODS,m)))throw Error('Unknown attack or modifier.');num(a,'damage',0,100000);num(a,'interval',.15,300);num(a,'range',20,1500);num(a,'count',1,12);if(a.target&&!p[k].some(u=>u.id===a.target))throw Error('Missing summon target.');}}
 for(const w of p.lawns){num(w,'rows',3,7);num(w,'cols',6,12);if(!Number.isInteger(w.rows)||!Number.isInteger(w.cols)||!Array.isArray(w.tiles)||w.tiles.length!==w.rows*w.cols||w.tiles.some(t=>!Object.hasOwn(TILES,t)))throw Error('Invalid lawn grid.');if(!['none','night','rain','sunshower','fog','meteor','tide'].includes(w.gimmick))throw Error('Unknown gimmick.');num(w,'gimmickInterval',5,120);}
 for(const l of p.levels){const w=p.lawns.find(w=>w.id===l.lawnId);if(!w)throw Error('Level references a missing lawn.');for(const [k,min,max] of [['sun',0,99999],['sunInterval',1,120],['sunValue',1,1000],['waves',1,100],['spawnInterval',.5,60],['waveDuration',10,180],['seedSlots',1,16]])num(l,k,min,max);if(!Array.isArray(l.allowed)||l.allowed.some(id=>!p.plants.some(u=>u.id===id)))throw Error('Missing seed packet.');if(!Array.isArray(l.pool)||l.pool.length>2000)throw Error('Invalid zombie pool.');for(const e of l.pool){if(!p.zombies.some(z=>z.id===e.id))throw Error('Missing pool zombie.');num(e,'weight',.1,1000);num(e,'minWave',1,100);}if(!Array.isArray(l.preplaced)||l.preplaced.length>200||l.preplaced.some(e=>!p.plants.some(u=>u.id===e.id)||!Number.isInteger(e.row)||!Number.isInteger(e.col)||e.row<0||e.row>=w.rows||e.col<0||e.col>=w.cols))throw Error('Invalid pre-planted setup.');if(!Array.isArray(l.dialogue)||l.dialogue.length>100||l.dialogue.some(d=>typeof d.name!=='string'||typeof d.text!=='string'))throw Error('Invalid dialogue.');if(!Array.isArray(l.rules)||l.rules.length>100)throw Error('Invalid event rules.');for(const r of l.rules){if(!['time','wave','repeat'].includes(r.trigger)||!['sun','spawn','heal','damage','message'].includes(r.action))throw Error('Unknown event rule.');num(r,'at',1,9999);num(r,'amount',1,9999);if(r.target&&!p.zombies.some(z=>z.id===r.target))throw Error('Missing event zombie.');}}
 validateNewFields(p,num);validateStateMedia(p,num);
 for(const c of p.campaigns)if(!Array.isArray(c.levels)||c.levels.some(id=>!p.levels.some(l=>l.id===id)))throw Error('Campaign references a missing level.');
 validateLawnExtras(p);
 const walk=o=>{if(!o||typeof o!=='object')return;for(const [k,v] of Object.entries(o)){if(['__proto__','constructor','prototype'].includes(k))throw Error('Unsafe property.');if(['art','idle','action','death','projectile','portrait','thumbnail','animation','sound','background','music','voice','attackSound','deathSound','spawnSound'].includes(k)&&v&&!(typeof v==='object'&&['idle','death'].includes(k))){if(!validData(v,/sound|music|voice/i.test(k)))throw Error('Invalid embedded media.');if(v.startsWith('data:image/svg+xml')){const s=un64(v.split(',')[1]);if(/<script|on\w+\s*=|javascript:|<foreignObject|<image|<use|<animate|<set|(?:href|src)\s*=/i.test(s))throw Error('SVG contains unsupported active content.');}}walk(v);}};walk(p);return p;
}
$('#packFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>250*1024*1024)throw Error('Pack is larger than 250 MB.');const p=validatePack(JSON.parse(await f.text()));if(mergeImport){const map=new Map();for(const k of ['plants','zombies','lawns','levels','campaigns'])p[k].forEach(o=>map.set(o.id,uid()));const remap=o=>{if(Array.isArray(o))return o.map(remap);if(o&&typeof o==='object')return Object.fromEntries(Object.entries(o).map(([k,v])=>[k,remap(v)]));return typeof o==='string'&&map.has(o)?map.get(o):o;};const mapped=remap(p);for(const k of ['plants','zombies','lawns','levels','campaigns'])project[k].push(...mapped[k]);project.progress.unlocked.push(...mapped.progress.unlocked);project.progress.completed.push(...mapped.progress.completed);}else{if(!confirm('Replace the current project with this pack?'))return;project=p;selected={};}save();render();toast('Pack imported successfully.');}catch(err){toast('Import stopped: '+err.message);}};
function renderHelp(){shell(`<section class="panel help"><h2>From idea to invasion</h2><ol><li><p><b>Plant and zombie makers:</b> create a blank unit, name it and set stats. Add as many attack behaviors as you need. Interval controls its timer; range uses the 900-pixel battlefield width. Amount controls damage, sun produced, health restored or push distance. Burst count also controls chain targets and summoned allies.</p></li><li><p><b>Media:</b> import PNG or GIF sprites and MP3 or WAV sound. Files are converted into base64 URLs automatically. You can also paste complete base64 data URLs. State art / SFX has 28 states with normal, damaged and critical variants. Every recipe can override its animation and sound. Use PNG/GIF for art and MP3/WAV for audio; each state has its own hold time and volume.</p></li><li><p><b>Lawns:</b> paint tiles and attach your background and looping music. Water needs an aquatic plant or a platform; roofs need a pot. Create your own aquatic or roof platform units and enable their Platform trait so other plants can be placed on top. Flying zombies ignore terrain and mines. Ice speeds zombies, mud slows them, power tiles boost attacks, and portals skip one column.</p></li><li><p><b>Levels:</b> define seed choices, wave timing and a weighted zombie pool. Entries become eligible at their first wave. Each entry is rolled by relative weight among zombies that can use the lawn. Spawns choose a compatible lane. Finite levels stop spawning after the last wave timer; defeat the survivors to win. Endless levels increase health and spawn speed each wave.</p></li><li><p><b>Dialogue and rules:</b> opening dialogue pauses the battle until you finish reading. Rules trigger once at a time / wave, or repeatedly on an interval. Use them for reinforcement waves, sun bonuses, healing, damage and announcements.</p></li><li><p><b>Campaigns:</b> arrange levels with the arrow buttons. Win a stage to continue to the next. All stages are also available in Play & explore. Export a campaign pack or your entire project from Pack library.</p></li></ol><h2>New in 1.1</h2><p>100 new plant-only and 100 new zombie-only abilities join the 210 shared recipes. Each maker offers 310 choices. World, level and campaign studios now use tabs; collections and Play have search. Packs from earlier editions remain compatible.</p><h2>Empty workshop</h2><p>This edition starts empty, with no preset units, levels, lawns, campaigns, character art or music. The supplied menu backgrounds and logo remain interface assets. Create or import your own content.</p><p>On a tablet, use the bottom Stats / Abilities / State art / SFX / My units toolbar. Done saves and closes the editor. Numeric fields have touch steppers. Drag across lawn tiles to paint, and use Undo / Redo if needed. Both tablet orientations are supported.</p><p>State media is owned by each entity. Select its state and health variant, import an animation and sound, and use Preview art + SFX. Sound can loop for persistent states. Attack recipes have optional overrides. NPC dialogue lines also support entry, talking, idle and exit media.</p><h2>Interface</h2><p>The main menu now follows the supplied visual references. Make plant / Make zombie opens a fresh creation. Edit plant / Edit zombie opens the spotlight maker. Choose Edit stats, Abilities, or Import art / sounds to open its editor. Choose plant / zombie opens your collection. Save stores the creation, and Back to menu returns home.</p><p>410 abilities are available. The 210 shared recipes are joined by 100 plant-only and 100 zombie-only additions. Search their names, descriptions or mechanics, then click a catalog entry to add its recipe. Some abilities require a summon / transform target, an active status, particular terrain, or a resource cost; read the description above each recipe.</p><h2>Progression and environments</h2><p>Each unit maker offers 310 behaviors, with descriptions above each recipe. Plant speed moves plants to the right; 0 keeps them stationary. Movement respects blocked tiles, terrain and other plants. Platforms carry their riders. Plants retire at the right edge.</p><p>Mark a plant Starts locked, then choose it under Unlock on win in a level. Winning permanently earns its packet for all levels that allow it. A level’s Locked checkbox always overrides progression. Pack library resets earned progress. Level and campaign covers accept PNG/GIF. Weather can be inherited from the lawn or overridden per level; disable gameplay effects for purely visual weather. Rain slows zombies, snow slows movement, wind pushes projectiles right, heat boosts sky sun, and storms strike zombies.</p><h2>Playing</h2><p>Choose up to the level’s seed-slot limit, then start. Click a packet and click a tile to plant. Click sun tokens to collect. Use Shovel to remove the top plant, then its platform. Each lane gets one emergency lawn mower. Pause freezes all timers. Conveyor levels provide random free packets every four seconds. Use the sound button to mute all audio.</p><h2>Attack notes</h2><p>Normal projectiles cannot clear a roof slope from the first three columns. Lobbers, lasers, homing and chain attacks can. Melee, chomp, mine and explosion attacks cannot target flying zombies. Explosions and mines consume their user. Freeze, push and pull affect all enemies within range; healing and buffs affect allies. Poison and burn deal damage over time; stun briefly stops movement and attacks. Summoning and transforming require a target unit in the recipe. Death-spawn uses the first summon target. Summons are capped to keep the game responsive.</p><h2>Saving and sharing</h2><p>Changes save automatically using IndexedDB when the browser permits it. Private mode or browser cleanup can erase local storage. Export .pvzpack files as backups. Standalone HTML exports embed your entire project and can be reopened offline. This edition uses a new engine and interface informed by the uploaded framework’s base64 media slots and stackable abilities. It does not import the old framework’s save format.</p><p class="notice">Fan-made creative sandbox. Plants vs. Zombies belongs to EA / PopCap. No starter gameplay content is bundled. No external libraries, fonts, services or network requests are required.</p></section>`,'Field guide','A few seeds of knowledge.');}
function prepareBattle(levelId,campaignId=null,campaignIndex=0){const l=project.levels.find(x=>x.id===levelId),w=project.lawns.find(x=>x.id===l?.lawnId);if(!l||!w)return toast('This level needs a valid lawn.');if(!l.allowed.length)return toast('Choose available plants in the Level maker first.');if(!l.pool.length)return toast('Add at least one zombie to the spawn pool first.');const eligible=l.pool.some(p=>p.minWave===1&&compatibleRows(project.zombies.find(z=>z.id===p.id),w).length);if(!eligible)return toast('Wave 1 needs a pool zombie compatible with at least one lane.');page='play';const choices=project.plants.filter(p=>l.allowed.includes(p.id)),available=choices.filter(p=>!plantLockReason(p,l));if(!available.length)return toast('No unlocked plants are allowed here. Adjust the level locks or earn a victory unlock first.');let pick=available.slice(0,Math.min(l.seedSlots,available.length)).map(p=>p.id);shell(`<section class="panel">${thumbnailHTML(l)}<h2>${esc(l.name)}</h2><p class="muted">Select up to ${l.seedSlots} seed packets. ${l.conveyor?'Conveyor mode randomly supplies these packets for free.':'Build a balanced team before starting.'}</p><div class="cards" id="pickCards">${choices.map(p=>`<button ${plantLockReason(p,l)?'disabled':''} class="card pick ${pick.includes(p.id)?'selected':''}" data-pick="${p.id}" style="outline:${pick.includes(p.id)?'3px solid #83a843':'none'}"><img class="icon" src="${esc(defaultEntityImage(p)||EMPTY_IMAGE)}" alt=""><h3>${esc(p.name)}</h3><span class="pill">${p.cost} sun</span><span class="pill">${p.hp} HP</span>${plantLockReason(p,l)?`<p>🔒 ${plantLockReason(p,l)}</p>`:''}</button>`).join('')}</div><div class="row" style="margin-top:24px"><button class="primary" id="startBattle">▷ Defend the lawn</button><button id="backPlay">Back</button><span id="pickCount">${pick.length} / ${l.seedSlots} selected</span></div></section>`,'Choose your garden',w.name);$$('[data-pick]').forEach(b=>b.onclick=()=>{const id=b.dataset.pick;if(pick.includes(id))pick=pick.filter(x=>x!==id);else if(pick.length<l.seedSlots)pick.push(id);else return toast('All seed slots are filled. Deselect one first.');b.style.outline=pick.includes(id)?'3px solid #83a843':'none';$('#pickCount').textContent=`${pick.length} / ${l.seedSlots} selected`;});$('#backPlay').onclick=()=>navigate('play');$('#startBattle').onclick=()=>{if(!pick.length)return toast('Choose at least one plant.');startBattle(l,w,pick,campaignId,campaignIndex);};}
