function syncNodes(map,items,create,paint){const ids=new Set(items.map(e=>e.id));for(const [id,el] of map)if(!ids.has(id)||!el.isConnected){el.remove();map.delete(id);}for(const e of items){let el=map.get(e.id);if(!el){el=create(e);map.set(e.id,el);$('#sprites').appendChild(el);}paint(el,e);}}
