function frame(t,id){if(!battle||battle.id!==id)return;const b=battle,dt=Math.min(.05,(t-b.last)/1000);b.last=t;if(!b.paused&&!b.dialogOpen&&!b.ended)update(dt);renderBattle();if(battle&&battle.id===id&&!b.ended)requestAnimationFrame(t=>frame(t,id));}
function endBattle(win){const b=battle;if(b.ended)return;b.ended=true;const rewards=win?awardVictory(b.l):[];stopAudio();stopEntityAudio();const campaign=project.campaigns.find(c=>c.id===b.campaignId),next=win&&campaign?.levels[b.campaignIndex+1];$('#overlay').innerHTML=`<div class="veil"><div class="dialog"><div class="eyebrow">${win?'A job well grown':'The horde got through'}</div><h2>${win?'Your garden stands!':'The zombies won this round.'}</h2><p>${b.kills} zombies defeated in ${Math.floor(b.time)} seconds. ${win&&campaign&&!next?'Campaign complete!':''}</p>${rewards.length?`<div class="unlocksWon"><h3>New plants unlocked!</h3>${rewards.map(p=>`<span><img src="${esc(defaultEntityImage(p)||EMPTY_IMAGE)}" alt="">${esc(p.name)}</span>`).join('')}</div>`:''}<div class="row">${next?'<button class="primary" id="nextLevel">Next level →</button>':''}<button id="retry">Try again</button><button id="returnPlay">Back to menu</button></div></div></div>`;if(next)$('#nextLevel').onclick=()=>{battle=null;prepareBattle(next,campaign.id,b.campaignIndex+1);};$('#retry').onclick=()=>{battle=null;prepareBattle(b.l.id,b.campaignId,b.campaignIndex);};$('#returnPlay').onclick=()=>navigate('play');}
async function boot(){const embedded=$('#embeddedProject').textContent.trim();let supplied=null;if(embedded){try{supplied=validatePack(JSON.parse(un64(embedded)));}catch(e){toast('Embedded project could not load: '+e.message);}}try{db=await new Promise((resolve,reject)=>{const req=indexedDB.open('pvz-builder-offline-v13'+(embedded?'-'+Array.from(embedded).reduce((h,c)=>(Math.imul(h,31)+c.charCodeAt(0))|0,0):''),1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});const saved=await new Promise(resolve=>{const req=db.transaction('projects').objectStore('projects').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>resolve(null);});if(saved){try{project=validatePack(saved);savedState='Saved on this device';}catch{project=supplied||defaults();savedState='Empty workshop ready';}}else if(supplied){project=supplied;savedState='Embedded pack loaded';}}catch{if(supplied)project=supplied;savedState='Export packs to keep your changes';}render();}
window.addEventListener('beforeunload',()=>{if(db){try{db.transaction('projects','readwrite').objectStore('projects').put(project,'current');}catch{}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&battle&&!battle.paused&&!battle.dialogOpen&&!battle.ended)$('#pause')?.click();});
