function migrateProject(p){
 if(!p||typeof p!=='object'||!['plants','zombies','lawns','levels','campaigns'].every(k=>Array.isArray(p[k])))return p;
 for(const u of [...p.plants,...p.zombies])if(u&&typeof u==='object'){u.startLocked??=false;migrateEntityStates(u);}
 for(const w of p.lawns)if(w&&typeof w==='object'){w.weather??='clear';w.weatherIntensity??=1;w.weatherEffects??=true;}
 for(const l of p.levels)if(l&&typeof l==='object'){l.thumbnail??='';l.weather??='inherit';l.weatherIntensity??=1;l.weatherEffects??=true;l.locked??=[];l.unlocks??=[];}
 for(const c of p.campaigns)if(c&&typeof c==='object')c.thumbnail??='';
 p.progress??={unlocked:[],completed:[]};return p;
}
function validateNewFields(p,num){
 for(const u of [...p.plants,...p.zombies])if(typeof u.startLocked!=='boolean')throw Error('Invalid starting lock.');
 for(const [items,inherit] of [[p.lawns,false],[p.levels,true]])for(const o of items){if(!Object.hasOwn(WEATHER,o.weather)&&!(inherit&&o.weather==='inherit'))throw Error('Unknown weather.');num(o,'weatherIntensity',.2,2);if(typeof o.weatherEffects!=='boolean')throw Error('Invalid weather effects flag.');}
 for(const l of p.levels)for(const k of ['locked','unlocks'])if(!Array.isArray(l[k])||l[k].some(id=>!p.plants.some(u=>u.id===id)))throw Error('Invalid level plant locks / rewards.');
 if(!p.progress||!Array.isArray(p.progress.unlocked)||!Array.isArray(p.progress.completed)||p.progress.unlocked.some(id=>!p.plants.some(u=>u.id===id))||p.progress.completed.some(id=>!p.levels.some(l=>l.id===id)))throw Error('Invalid earned progression.');
}
function weatherFields(o,inherit){return `${selectField('weather','Weather',o.weather,inherit?{inherit:'Use lawn weather',...WEATHER}:WEATHER)}${field('weatherIntensity','Weather intensity',o.weatherIntensity,'number',.2,2)}<div class="field">Simulation${checkField('weatherEffects','Enable weather gameplay effects',o.weatherEffects)}</div>${inherit?'<p class="field full muted">Use lawn weather also inherits the lawn’s intensity and gameplay settings. Choose another type here to use this level’s settings.</p>':''}`;}
function resolveWeather(l,w){const o=l.weather==='inherit'?w:l;return {type:o.weather||'clear',intensity:o.weatherIntensity||1,effects:o.weatherEffects!==false};}
function thumbnailHTML(o){return o.thumbnail?`<img class="cover" src="${esc(o.thumbnail)}" alt="${esc(o.name)} cover">`:'';}
function plantLockReason(u,l){if(l.locked?.includes(u.id))return 'Locked in this level';if(u.startLocked&&!project.progress.unlocked.includes(u.id))return 'Earn this plant by winning a level';return '';}
function awardVictory(l){const earned=[];if(!project.progress.completed.includes(l.id))project.progress.completed.push(l.id);for(const id of l.unlocks||[]){const p=project.plants.find(p=>p.id===id);if(p&&!project.progress.unlocked.includes(id)){project.progress.unlocked.push(id);earned.push(p);}}save();return earned;}
function weatherMovement(e){const w=battle.weather;if(!w.effects)return 1;if(w.type==='snow')return Math.max(.35,1-.3*w.intensity);if(w.type==='rain'&&e.side==='zombie')return Math.max(.5,1-.15*w.intensity);return 1;}
function movePlant(e,dt){
 const b=battle;if(e.dead||e.u.speed<=0||newMovementLocked(e))return;const supported=b.entities.find(t=>!t.dead&&t.id===e.supportId);if(supported)return;
 const near=b.entities.some(t=>!t.dead&&t!==e&&t.row===e.row&&t.x>e.x&&t.x-e.x<65&&(t.side==='zombie'||t.u.traits.includes('platform')===e.u.traits.includes('platform')));if(near)return;
 let nx=Math.max(15,e.x+e.u.speed*weatherMovement(e)*newMovementFactor(e)*(e.status.slow>b.time?.45:1)*dt);
 if(nx>920){kill(e,false);return;}let col=Math.min(b.w.cols-1,Math.floor(nx/900*b.w.cols)),tile=tileAt(e.row,col);
 const platform=b.entities.find(t=>!t.dead&&t!==e&&t.side==='plant'&&t.row===e.row&&t.col===col&&t.u.traits.includes('platform'));
 if(tile==='blocked'||(e.u.placement==='water'&&tile!=='water')||(e.u.placement==='roof'&&tile!=='roof')||(e.u.placement==='ground'&&['water','roof'].includes(tile)&&!e.u.traits.includes('platform')&&!platform))return;
 const dx=nx-e.x;e.x=nx;e.col=col;
 if(e.u.traits.includes('platform'))b.entities.filter(t=>!t.dead&&t.supportId===e.id).forEach(t=>{t.x+=dx;t.col=col;});
}
function terrainValid(e,row,col){if(row<0||row>=battle.w.rows||e.laneSealUntil>battle.time||e.anchorUntil>battle.time)return false;if(e.side==='zombie')return compatibleRows(e.u,battle.w).includes(row);return canPlace(e.u,row,col,false);}
function reposition(e,row,col){if(!terrainValid(e,row,col))return false;e.row=row;if(e.side==='plant'){e.col=col;e.x=cellX(col);e.supportId=battle.entities.find(t=>!t.dead&&t!==e&&t.side==='plant'&&t.row===row&&t.col===col&&t.u.traits.includes('platform'))?.id||null;if(e.u.traits.includes('platform'))battle.entities.filter(t=>!t.dead&&t.supportId===e.id).forEach(t=>{t.row=row;t.col=col;t.x=e.x;});}return true;}
function alliesOf(e,range){return battle.entities.filter(t=>!t.dead&&t.side===e.side&&Math.hypot(t.x-e.x,(t.row-e.row)*500/battle.w.rows)<=range);}
function allEnemiesOf(e,range){return battle.entities.filter(t=>!t.dead&&t.side!==e.side&&Math.hypot(t.x-e.x,(t.row-e.row)*500/battle.w.rows)<=range);}
function zone(e,type,x,row,damage,a){if(battle.zones.length>=80)return;const mortar=type==='mortar';battle.zones.push({id:uid(),type,x,row,side:e.side,source:e,damage,a:clone(a),radius:type==='trap'||type==='fireTrail'?70:110,starts:battle.time+(mortar?1.2:0),until:battle.time+(mortar?1.4:type==='trap'?6:type==='fireTrail'?5:4),fired:false});}
function performExtra(e,a,dmg){
 if(!Object.hasOwn(BEHAVIOR_HELP,a.type))return null;
 const b=battle,dir=e.side==='plant'?1:-1,near=allEnemiesOf(e,a.range).sort((x,y)=>Number(y.status.mark>b.time)-Number(x.status.mark>b.time)||Math.hypot(x.x-e.x,(x.row-e.row)*100)-Math.hypot(y.x-e.x,(y.row-e.row)*100)),target=near[0],allies=alliesOf(e,a.range),weak=allies.filter(t=>!t.u.traits.includes('platform')).sort((x,y)=>x.hp/x.maxHp-y.hp/y.maxHp)[0];
 switch(a.type){
 case 'cleanse':for(const t of allies)for(const k of ['slow','stun','poison','burn','weaken','silence','root','curse','mark'])delete t.status[k];effect(e.x,e.row,'CLEANSE','#d7f7e0');return true;
 case 'barrier':for(const t of allies){t.shieldHP=Math.max(t.shieldUntil>b.time?t.shieldHP||0:0,dmg);t.shieldUntil=b.time+a.interval+1;}effect(e.x,e.row,'◇','#abd9ef');return true;
 case 'reflect':e.reflectUntil=b.time+3;effect(e.x,e.row,'↶','#d6b9ef');return true;
 case 'dodge':e.evade=1;return true;
 case 'berserk':e.status.frenzy=b.time+4;e.hp=Math.max(1,e.hp-e.maxHp*.05);return true;
 case 'grow':{const n=Math.min(dmg,e.u.hp*5-e.maxHp);e.maxHp+=Math.max(0,n);e.hp+=Math.max(0,n);effect(e.x,e.row,'GROW','#d8f191');return true;}
 case 'sunSteal':b.sun=Math.max(0,b.sun+(e.side==='plant'?dmg:-dmg));effect(e.x,e.row,e.side==='plant'?'+☀':'−☀','#f9dd83');return true;
 case 'sunMagnet':{const suns=b.suns.filter(s=>Math.hypot(s.x-e.x,s.y-rowY(e.row))<=a.range);if(!suns.length)return false;b.sun+=suns.reduce((n,s)=>n+s.value,0);const ids=new Set(suns.map(s=>s.id));b.suns=b.suns.filter(s=>!ids.has(s.id));return true;}
 case 'cooldownReduce':if(e.side==='plant'){for(const id of b.seeds)b.cooldowns[id]=Math.max(b.time,(b.cooldowns[id]||b.time)-dmg);}else for(const t of allies)if(t!==e)t.timers=t.timers.map(n=>Math.max(0,n-dmg));effect(e.x,e.row,'FAST','#d0e9e7');return true;
 case 'trap':case 'poisonCloud':case 'fireTrail':zone(e,a.type,e.x-(a.type==='fireTrail'?dir*35:0),e.row,dmg,a);return true;
 case 'blinkDodge':{for(const row of [e.row-1,e.row+1])if(reposition(e,row,Math.max(0,e.col))){e.evade=1;effect(e.x,e.row,'BLINK');return true;}return false;}
 case 'proximityHeal':if(!weak||weak.hp>=weak.maxHp)return false;weak.hp=Math.min(weak.maxHp,weak.hp+dmg);effect(weak.x,weak.row,'+','#bdeaa3');return true;
 case 'rescue':{if(!weak||weak.hp>=weak.maxHp)return false;if(weak.side==='zombie'){weak.x=Math.min(920,weak.x+120);}else{let found=false;for(let c=Math.max(0,Math.floor(e.x/900*b.w.cols)-1);c>=0&&!found;c--)found=reposition(weak,weak.row,c);if(!found)return false;}weak.hp=Math.min(weak.maxHp,weak.hp+dmg);effect(weak.x,weak.row,'RESCUED','#bdeaa3');return true;}
 case 'globalStrike':{const targets=b.entities.filter(t=>!t.dead&&t.side!==e.side);if(!targets.length)return false;targets.forEach(t=>{damage(t,dmg,e,a);effect(t.x,t.row,'✧',e.u.color);});return true;}
 case 'crossLaser':{const targets=b.entities.filter(t=>!t.dead&&t.side!==e.side&&(t.row===e.row||Math.abs(t.x-e.x)<50)&&Math.abs(t.x-e.x)<=a.range);if(!targets.length)return false;targets.forEach(t=>damage(t,dmg,e,a));effect(e.x,e.row,'╋',e.u.color);return true;}
 case 'cleave':{const targets=near.filter(t=>Math.hypot(t.x-e.x,(t.row-e.row)*500/b.w.rows)<=Math.min(110,a.range)&&!t.u.traits.includes('flying'));if(!targets.length)return false;targets.forEach(t=>damage(t,dmg,e,a));effect(e.x,e.row,'SWEEP',e.u.color);return true;}
 }
 if(!target)return false;
 switch(a.type){
 case 'execute':damage(target,target.hp/target.maxHp<=.3?target.hp/(1-target.u.armor)+1:dmg,e,a);effect(target.x,target.row,'✕');return true;
 case 'percentHit':damage(target,target.hp*Math.min(90,dmg)/100,e,a);return true;
 case 'armorBreak':target.u.armor=Math.max(0,target.u.armor-dmg/100);damage(target,dmg*.25,e,a);effect(target.x,target.row,'CORRODE');return true;
 case 'weaken':case 'silence':case 'curse':case 'mark':target.status[a.type]=b.time+(a.type==='mark'?6:4);if(a.type!=='mark')damage(target,dmg*.25,e,a);effect(target.x,target.row,a.type.toUpperCase());return true;
 case 'root':near.forEach(t=>{t.status.root=b.time+4;});effect(e.x,e.row,'ROOT');return true;
 case 'shieldBreak':target.shieldHP=0;target.shieldUntil=0;target.reflectUntil=0;damage(target,dmg,e,a);effect(target.x,target.row,'SHATTER');return true;
 case 'laneSwap':for(const r of [target.row+1,target.row-1])if(reposition(target,r,Math.max(0,target.col))){damage(target,dmg*.25,e,a);effect(target.x,target.row,'↕');return true;}return false;
 case 'scatterShot':for(let burst=0;burst<a.count;burst++)for(let i=-2;i<=2;i++){const before=b.bullets.length;makeBullet(e,a,dmg,e.row,dir,burst*.12);if(b.bullets.length>before)b.bullets.at(-1).vy=i*75;}return true;
 case 'mortar':zone(e,'mortar',target.x,target.row,dmg,a);effect(target.x,target.row,'◎','#f6bf7d');return true;
 case 'ricochet':case 'splitter':for(let i=0;i<(a.type==='ricochet'?1:a.count);i++)makeBullet(e,a,dmg,e.row,dir,i*.12);return true;
 }
 return false;
}
function fragmentBullet(p,t){const fake={...p.source,x:t.x,u:{...p.source.u,projectile:p.art},side:p.side};for(const row of [t.row-1,t.row,t.row+1])if(row>=0&&row<battle.w.rows){const n=battle.bullets.length;makeBullet(fake,{...p.a,type:'shot',count:1},p.damage*.4,row,p.dir);if(battle.bullets.length>n)battle.bullets.at(-1).hit.add(t.id);}effect(t.x,t.row,'✣',p.color);}
function updateZones(dt){const b=battle;for(const z of b.zones){if(b.time<z.starts||b.time>=z.until)continue;const targets=b.entities.filter(t=>!t.dead&&t.side!==z.side&&Math.hypot(t.x-z.x,(t.row-z.row)*500/b.w.rows)<=z.radius&&!(z.type==='trap'&&t.u.traits.includes('flying')));if(z.type==='mortar'){if(!z.fired){targets.forEach(t=>damage(t,z.damage,z.source,z.a));z.fired=true;effect(z.x,z.row,'BOOM','#efb16c');}}else targets.forEach(t=>{damage(t,z.damage*dt,z.source,z.a);if(z.type==='poisonCloud')t.status.poison=b.time+4;if(z.type==='fireTrail')t.status.burn=b.time+3;});}b.zones=b.zones.filter(z=>b.time<z.until);}
function renderZones(){if(!domMaps.zone)domMaps.zone=new Map();syncNodes(domMaps.zone,battle.zones,z=>{const el=document.createElement('div');el.className='hazardZone';return el;},(el,z)=>{el.className='hazardZone '+z.type;el.style.left=z.x/9+'%';el.style.top=(rowY(z.row)-25)/5+'%';el.style.width=z.radius*2/9+'%';el.style.height=z.radius*2/5+'%';el.textContent=z.type==='mortar'?'◎':'';});}
function updateWeather(dt){const b=battle,w=b.weather;if(w.effects&&w.type==='storm'&&b.time>=b.nextWeather){b.nextWeather=b.time+12/w.intensity;const rods=b.entities.filter(e=>!e.dead&&e.lightningRodUntil>b.time);if(rods.length){const rod=rods[0];rod.lightningCharge=(rod.lightningCharge||0)+35*w.intensity;effect(rod.x,rod.row,'CHARGED','#fff6aa');return;}const targets=b.entities.filter(e=>!e.dead&&e.side==='zombie');if(targets.length){const t=targets[Math.floor(Math.random()*targets.length)];damage(t,35*w.intensity);effect(t.x,t.row,'ϟ','#f7f0b3');b.flashUntil=b.time+.15;}}}
function renderWeather(){const canvas=$('#weatherCanvas');if(!canvas)return;const ctx=canvas.getContext('2d');if(!ctx)return;const {type,intensity}=battle.weather,t=battle.time;ctx.clearRect(0,0,900,500);if(type==='clear')return;
 if(type==='fog'){const g=ctx.createLinearGradient(0,0,900,0);g.addColorStop(0,'#e9f0e100');g.addColorStop(1,`rgba(223,234,220,${.4*intensity})`);ctx.fillStyle=g;ctx.fillRect(0,0,900,500);for(const e of battle.entities.filter(e=>!e.dead&&e.lanternUntil>t)){ctx.save();ctx.globalCompositeOperation='destination-out';ctx.beginPath();ctx.arc(e.x,rowY(e.row)-25,e.lanternRange||130,0,Math.PI*2);ctx.fill();ctx.restore();}return;}
 if(type==='heat'){ctx.fillStyle=`rgba(255,189,74,${.06*intensity})`;ctx.fillRect(0,0,900,500);for(let i=0;i<12;i++){ctx.strokeStyle='#ffd68035';ctx.beginPath();ctx.ellipse((i*83+t*7)%950,420+Math.sin(i+t)*35,40,6,0,0,Math.PI*2);ctx.stroke();}return;}
 const count=Math.floor((type==='snow'?65:50)*intensity);ctx.lineWidth=type==='wind'?1.5:1;for(let i=0;i<count;i++){const speed=type==='snow'?28:type==='leaves'?45:260,x=(((Math.sin(i*12.9898+1)*43758.5453%1+1)%1*1000+t*(type==='wind'?190:35))%1000)-50,y=(((Math.sin(i*78.233+3)*12345.678%1+1)%1*550+t*speed)%550)-25;ctx.beginPath();if(type==='snow'){ctx.fillStyle='#ffffffcc';ctx.arc(x+Math.sin(t+i)*12,y,2+i%3,0,Math.PI*2);ctx.fill();}else if(type==='leaves'){ctx.save();ctx.translate(x,y);ctx.rotate(t+i);ctx.fillStyle=['#dcb05a','#bb7546','#dec66d'][i%3];ctx.ellipse(0,0,5,2,0,0,7);ctx.fill();ctx.restore();}else{ctx.strokeStyle=type==='wind'?'#f0f8d779':'#c5ecff88';ctx.moveTo(x,y);ctx.lineTo(x+(type==='wind'?45:7),y+(type==='wind'?0:18));ctx.stroke();}}
 if(type==='storm'){ctx.fillStyle=battle.flashUntil>t?'#ffffdf88':'#1b284b28';ctx.fillRect(0,0,900,500);}
}

